create extension if not exists pgcrypto;
create table organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table profiles(user_id uuid primary key references auth.users(id) on delete cascade,organization_id uuid not null references organizations(id),full_name text not null,role text not null check(role in('agency_admin','account_manager','creative_staff')),created_at timestamptz not null default now());
create table clients(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),portal_user_id uuid unique references auth.users(id),name text not null,contact_email text not null,created_at timestamptz not null default now());
create table projects(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),client_id uuid not null references clients(id),name text not null,status text not null default 'active' check(status in('active','on_hold','completed','archived')),hourly_rate numeric(10,2),created_at timestamptz not null default now());
create table briefs(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,raw_client_input text not null,drafted_content jsonb,status text not null default 'drafting' check(status in('drafting','review','approved')),approved_by uuid references auth.users(id),approved_at timestamptz,created_at timestamptz not null default now());
create table deliverables(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,name text not null,storage_path text not null,version integer not null default 1,status text not null default 'in_review' check(status in('in_review','changes_requested','approved')),approved_by uuid references auth.users(id),approved_at timestamptz,created_at timestamptz not null default now(),unique(project_id,name,version));
create table redline_comments(id uuid primary key default gen_random_uuid(),deliverable_id uuid not null references deliverables(id) on delete cascade,author_id uuid not null references auth.users(id),x_position numeric not null check(x_position between 0 and 100),y_position numeric not null check(y_position between 0 and 100),comment_text text not null,resolved boolean not null default false,resolved_by uuid references auth.users(id),resolved_at timestamptz,created_at timestamptz not null default now());
create table time_entries(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,user_id uuid not null references auth.users(id),task_description text not null,minutes integer not null check(minutes>0),billable boolean not null default true,invoiced boolean not null default false,created_at timestamptz not null default now());
create table invoices(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id),total_amount numeric(12,2) not null check(total_amount>=0),stripe_invoice_id text unique,status text not null default 'draft' check(status in('draft','sent','paid','overdue')),created_at timestamptz not null default now());
create table invoice_time_entries(invoice_id uuid not null references invoices(id) on delete cascade,time_entry_id uuid not null unique references time_entries(id),primary key(invoice_id,time_entry_id));
create table audit_events(id bigint generated always as identity primary key,organization_id uuid not null references organizations(id),actor_id uuid references auth.users(id),entity_type text not null,entity_id uuid not null,event_type text not null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function current_organization_id() returns uuid language sql stable security definer set search_path=public as $$select organization_id from profiles where user_id=auth.uid()$$;
create or replace function can_access_project(target_project uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from projects p left join clients c on c.id=p.client_id where p.id=target_project and (p.organization_id=current_organization_id() or c.portal_user_id=auth.uid()))$$;
create or replace function approve_deliverable(target_id uuid) returns void language plpgsql security definer set search_path=public as $$declare target_project uuid;begin select project_id into target_project from deliverables where id=target_id;if target_project is null or not can_access_project(target_project) then raise exception 'Access denied';end if;if exists(select 1 from redline_comments where deliverable_id=target_id and resolved=false) then raise exception 'All redline comments must be resolved before approval';end if;update deliverables set status='approved',approved_by=auth.uid(),approved_at=now() where id=target_id;insert into audit_events(organization_id,actor_id,entity_type,entity_id,event_type) select organization_id,auth.uid(),'deliverable',target_id,'deliverable.approved' from projects where id=target_project;end;$$;
create or replace function create_invoice_from_time(target_project uuid) returns uuid language plpgsql security definer set search_path=public as $$declare new_invoice uuid;calculated_total numeric(12,2);begin if not exists(select 1 from projects where id=target_project and organization_id=current_organization_id()) then raise exception 'Access denied';end if;select coalesce(sum((te.minutes/60.0)*p.hourly_rate),0) into calculated_total from time_entries te join projects p on p.id=te.project_id where te.project_id=target_project and te.billable=true and te.invoiced=false for update of te;if calculated_total<=0 then raise exception 'No uninvoiced time entries remain';end if;insert into invoices(project_id,total_amount) values(target_project,calculated_total) returning id into new_invoice;insert into invoice_time_entries(invoice_id,time_entry_id) select new_invoice,id from time_entries where project_id=target_project and billable=true and invoiced=false;update time_entries set invoiced=true where id in(select time_entry_id from invoice_time_entries where invoice_id=new_invoice);return new_invoice;end;$$;
alter table organizations enable row level security;alter table profiles enable row level security;alter table clients enable row level security;alter table projects enable row level security;alter table briefs enable row level security;alter table deliverables enable row level security;alter table redline_comments enable row level security;alter table time_entries enable row level security;alter table invoices enable row level security;alter table invoice_time_entries enable row level security;alter table audit_events enable row level security;
create policy org_profiles on profiles for select using(organization_id=current_organization_id());
create policy org_clients on clients for all using(organization_id=current_organization_id()) with check(organization_id=current_organization_id());
create policy clients_self on clients for select using(portal_user_id=auth.uid());
create policy project_access on projects for select using(can_access_project(id));
create policy project_staff_write on projects for all using(organization_id=current_organization_id()) with check(organization_id=current_organization_id());
create policy brief_access on briefs for select using(can_access_project(project_id));
create policy brief_staff_write on briefs for all using(exists(select 1 from projects p where p.id=project_id and p.organization_id=current_organization_id())) with check(exists(select 1 from projects p where p.id=project_id and p.organization_id=current_organization_id()));
create policy deliverable_access on deliverables for select using(can_access_project(project_id));
create policy deliverable_staff_write on deliverables for all using(exists(select 1 from projects p where p.id=project_id and p.organization_id=current_organization_id())) with check(exists(select 1 from projects p where p.id=project_id and p.organization_id=current_organization_id()));
create policy comment_access on redline_comments for select using(exists(select 1 from deliverables d where d.id=deliverable_id and can_access_project(d.project_id)));
create policy comment_create on redline_comments for insert with check(author_id=auth.uid() and exists(select 1 from deliverables d where d.id=deliverable_id and can_access_project(d.project_id)));
create policy comment_update on redline_comments for update using(author_id=auth.uid() or exists(select 1 from deliverables d join projects p on p.id=d.project_id where d.id=deliverable_id and p.organization_id=current_organization_id()));
create policy time_staff_only on time_entries for all using(exists(select 1 from projects p where p.id=project_id and p.organization_id=current_organization_id())) with check(exists(select 1 from projects p where p.id=project_id and p.organization_id=current_organization_id()));
create policy invoice_access on invoices for select using(can_access_project(project_id));
create policy invoice_staff_write on invoices for all using(exists(select 1 from projects p where p.id=project_id and p.organization_id=current_organization_id())) with check(exists(select 1 from projects p where p.id=project_id and p.organization_id=current_organization_id()));
create policy invoice_entries_staff on invoice_time_entries for select using(exists(select 1 from invoices i join projects p on p.id=i.project_id where i.id=invoice_id and p.organization_id=current_organization_id()));
create policy audit_staff on audit_events for select using(organization_id=current_organization_id());